// Meta comprueba tu URL con un GET (hub.mode, hub.verify_token, hub.challenge) al guardar el webhook en tu app.
// Inventa una cadena larga, ponla aquí y la misma en la app de Meta → WhatsApp / Messenger / Instagram → Webhooks.
const VERIFY_TOKEN = '<<VERIFY_TOKEN: cadena larga inventada por ti, la misma que pones en Meta>>';
const q = $input.first().json.query || {};
if (VERIFY_TOKEN.startsWith('<<')) {
  throw new Error('Rellena VERIFY_TOKEN en este nodo antes de verificar el webhook en Meta.');
}
if (q['hub.mode'] !== 'subscribe' || q['hub.verify_token'] !== VERIFY_TOKEN) {
  throw new Error('verify_token no coincide: Meta no podrá verificar la URL.');
}
return [{ json: { challenge: String(q['hub.challenge'] || '') } }];

// Comprueba que el aviso viene de Meta: cabecera X-Hub-Signature-256 = HMAC SHA-256 del cuerpo crudo con el
// secreto de tu app (App Dashboard → Configuración → Básica → Clave secreta). Sin esto, cualquiera que conozca la
// URL podría meter clics falsos en tu CRM.
// Necesita: el webhook con la opción «Raw Body» activada (ya lo está), el módulo crypto permitido
// (NODE_FUNCTION_ALLOW_BUILTIN=crypto en n8n autoalojado) y el secreto en la variable de entorno META_APP_SECRET
// (N8N_BLOCK_ENV_ACCESS_IN_NODE=false). Nunca pegues el secreto en este código.
const crypto = require('crypto');
let secreto = '';
try { secreto = $env.META_APP_SECRET || ''; } catch (e) { secreto = ''; }
if (!secreto) {
  throw new Error('Falta META_APP_SECRET en el entorno de n8n: sin él no se puede comprobar que el aviso es de Meta.');
}
const salida = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const cabeceras = item.json.headers || {};
  const firma = String(cabeceras['x-hub-signature-256'] || '');
  const crudo = await this.helpers.getBinaryDataBuffer(i, 'data');
  const esperada = 'sha256=' + crypto.createHmac('sha256', secreto).update(crudo).digest('hex');
  const ok = firma.length === esperada.length && crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperada));
  if (!ok) {
    throw new Error('Firma X-Hub-Signature-256 no válida: el aviso no viene de Meta o el secreto no es el de la app.');
  }
  let body = item.json.body;
  if (!body || typeof body !== 'object' || !Object.keys(body).length) {
    body = JSON.parse(crudo.toString('utf8'));
  }
  salida.push({ json: { headers: cabeceras, body } });
}
return salida;

// Una salida por mensaje entrante que viene de un anuncio. El referral solo llega en el primer mensaje tras el clic:
// si no lo guardas ahora, se pierde. Misma lógica que `capi.py origen` (los tests comparan las dos).
// WhatsApp Cloud API: entry[].changes[].value.messages[].referral (ctwa_clid, source_id = ID del anuncio).
// Messenger e Instagram: entry[].messaging[].message.referral (source ADS, ad_id); se ignoran los ecos.
const segundos = (t) => {
  const n = Math.floor(Number(t));
  if (!Number.isFinite(n) || n <= 0) return '';
  return String(n > 1e11 ? Math.floor(n / 1000) : n);
};
const salida = [];
for (const item of $input.all()) {
  const p = item.json.body || {};
  if (p.object === 'whatsapp_business_account') {
    for (const entrada of p.entry || []) {
      for (const cambio of entrada.changes || []) {
        const v = cambio.value || {};
        const contacto = (v.contacts || [])[0] || {};
        for (const m of v.messages || []) {
          const ref = m.referral;
          if (!ref) continue; // orgánico o mensaje posterior al primero
          const tel = String(m.from || contacto.wa_id || '');
          salida.push({ json: {
            mensajeria_canal: 'whatsapp',
            mensajeria_cuenta: String(entrada.id || ''),
            mensajeria_anuncio: String(ref.source_id || ''),
            mensajeria_clic: String(ref.ctwa_clid || ''),
            mensajeria_persona: tel || String(m.from_user_id || contacto.user_id || ''),
            mensajeria_entrada: segundos(m.timestamp),
            telefono: tel ? '+' + tel.replace(/^\+/, '') : '',
            numero_negocio: String((v.metadata || {}).phone_number_id || ''),
            aviso: ref.ctwa_clid ? '' : 'Anuncio de Estados: sin ctwa_clid, se emparejará por teléfono',
          } });
        }
      }
    }
  } else if (p.object === 'page' || p.object === 'instagram') {
    const canal = p.object === 'page' ? 'messenger' : 'instagram';
    for (const entrada of p.entry || []) {
      for (const ev of entrada.messaging || []) {
        const msg = ev.message || {};
        if (msg.is_echo) continue; // lo ha escrito el negocio
        const ref = msg.referral || ev.referral || (ev.postback || {}).referral;
        if (!ref || ref.source !== 'ADS') continue;
        salida.push({ json: {
          mensajeria_canal: canal,
          mensajeria_cuenta: String((ev.recipient || {}).id || entrada.id || ''),
          mensajeria_anuncio: String(ref.ad_id || ''),
          mensajeria_clic: '',
          mensajeria_persona: String((ev.sender || {}).id || ''),
          mensajeria_entrada: segundos(ev.timestamp),
          telefono: '',
          ref: String(ref.ref || ''),
          aviso: '',
        } });
      }
    }
  }
}
return salida;

// Rellena esto una vez por cliente. Nada de tokens aquí: el token va en la credencial del nodo «Enviar a la
// Conversions API» (Query Auth, nombre access_token).
const CONFIG = {
  DATASET_ID: '<<DATASET_ID: el dataset vinculado a tu WABA, Página o cuenta de Instagram>>',
  WABA_ID: '<<WABA_ID: ID de la cuenta de WhatsApp Business (si el CRM no lo guardó)>>',
  PAGE_ID: '<<PAGE_ID: ID de la Página (Messenger y WhatsApp sin ctwa_clid)>>',
  IG_ID: '<<IG_ID: ID de la cuenta profesional de Instagram>>',
  // Código de Events Manager → Probar eventos. Mientras exista, todo va como prueba.
  TEST_EVENT_CODE: '<<TEST_EVENT_CODE: código de Probar eventos>>',
  // Solo con el sí del cliente, después de verificar las pruebas: true y TEST_EVENT_CODE vacío.
  ENVIO_REAL_APROBADO: false,
  // Etapa del contrato §16 que cuenta como lead cualificado: cualificado, llamada, asistio o propuesta.
  CUALIFICA_EN: 'cualificado',
  MONEDA: 'EUR',
};
return $input.all().map((item) => ({ json: { ...item.json, config: CONFIG } }));

// Etapa del CRM (contrato §16) → evento de la Conversions API de mensajería. Misma tabla que `capi.py`.
// Sale un elemento solo si hay algo que mandar; si la etapa no tiene evento o el hito ya se envió, no sale nada.
// Los datos que faltan (venta sin importe, WhatsApp sin clic ni teléfono) paran el flujo con un error a la vista.
const ETAPAS = ["lead", "diagnostico", "cualificado", "llamada", "asistio", "propuesta", "ganado", "perdido"];
const EVENTOS_MENSAJERIA = ["LeadSubmitted", "QualifiedLead", "Purchase", "InitiateCheckout", "AddToCart", "ViewContent", "OrderCreated", "OrderShipped", "OrderDelivered", "OrderCanceled", "OrderReturned", "CartAbandoned", "RatingProvided", "ReviewProvided"];
const CANALES = ['whatsapp', 'messenger', 'instagram'];
const VENTANA_CLIC = 7 * 86400;
const valido = (v) => v !== undefined && v !== null && String(v).trim() !== '' && !String(v).startsWith('<<');
const segundos = (t) => {
  if (!valido(t)) return 0;
  const n = /^\d+(\.\d+)?$/.test(String(t)) ? Number(t) : Date.parse(String(t)) / 1000;
  if (!Number.isFinite(n)) return 0;
  return Math.floor(n > 1e11 ? n / 1000 : n);
};
const salida = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  const c = item.json.config || {};
  const canal = String(b.mensajeria_canal || '').trim().toLowerCase();
  if (!CANALES.includes(canal)) continue; // el contacto no entró por un anuncio de mensajes
  const etapa = String(b.etapa || '').trim().toLowerCase();
  if (!ETAPAS.includes(etapa)) throw new Error(`Etapa «${etapa}» desconocida: usa una del contrato §16 (${ETAPAS.join(', ')}).`);
  const cualificaEn = valido(c.CUALIFICA_EN) ? String(c.CUALIFICA_EN) : 'cualificado';
  let evento = null;
  if (etapa === 'lead') evento = 'LeadSubmitted';
  else if (etapa === 'ganado') evento = 'Purchase';
  else if (etapa === cualificaEn) evento = 'QualifiedLead';
  if (!evento) continue; // diagnóstico, llamada, asistencia, propuesta y perdido no tienen evento de mensajería
  if (!EVENTOS_MENSAJERIA.includes(evento)) throw new Error(`Evento ${evento} no admitido en mensajería.`);
  const enviados = String(b.mensajeria_enviados || '').split(',').map((s) => s.trim()).filter(Boolean);
  if (enviados.includes(evento)) continue; // Meta no deduplica la mensajería: cada hito, una sola vez
  const ahora = Math.floor(Date.now() / 1000);
  const momento = segundos(b.momento) || ahora;
  if (momento > ahora + 300) throw new Error('El momento del cambio de etapa está en el futuro.');
  if (ahora - momento > 7 * 86400) throw new Error('El cambio de etapa tiene más de 7 días: Meta lo rechaza. Envía en tiempo real.');
  const persona = String(b.mensajeria_persona || '').trim();
  const cuenta = String(b.mensajeria_cuenta || '').trim();
  const ud = {};
  let necesitaHash = false;
  let ph = '';
  if (canal === 'whatsapp') {
    const waba = valido(cuenta) ? cuenta : c.WABA_ID;
    if (!valido(waba)) throw new Error('Falta la WABA: guárdala al entrar la conversación o ponla en Configuración.');
    ud.whatsapp_business_account_id = String(waba);
    if (valido(b.mensajeria_clic)) {
      ud.ctwa_clid = String(b.mensajeria_clic).trim();
    } else {
      ph = String(b.telefono || '').replace(/\D/g, '').replace(/^00/, '');
      if (ph.length < 7 || ph.length > 15) throw new Error('WhatsApp sin ctwa_clid y sin teléfono con prefijo: no hay con qué emparejar.');
      if (!valido(c.PAGE_ID)) throw new Error('WhatsApp sin ctwa_clid necesita PAGE_ID en Configuración.');
      ud.page_id = String(c.PAGE_ID);
      necesitaHash = true; // el nodo siguiente hashea ph_normalizado con SHA-256
    }
  } else if (canal === 'messenger') {
    const pagina = valido(cuenta) ? cuenta : c.PAGE_ID;
    if (!valido(pagina) || !valido(persona)) throw new Error('Messenger necesita la Página y el PSID de quien escribió.');
    ud.page_id = String(pagina);
    ud.page_scoped_user_id = persona;
  } else {
    const ig = valido(cuenta) ? cuenta : c.IG_ID;
    if (!valido(ig) || !valido(persona)) throw new Error('Instagram necesita la cuenta profesional y el IGSID de quien escribió.');
    ud.instagram_business_account_id = String(ig);
    ud.ig_sid = persona;
  }
  const ev = { event_name: evento, event_time: momento, action_source: 'business_messaging', messaging_channel: canal, user_data: ud };
  if (evento === 'Purchase') {
    const valor = Number(b.valor);
    if (!valido(b.valor) || !Number.isFinite(valor) || valor <= 0) {
      throw new Error('Etapa ganado sin valor: pon el importe del proyecto en la oportunidad (Purchase necesita value).');
    }
    const moneda = String(valido(b.moneda) ? b.moneda : (c.MONEDA || '')).toUpperCase();
    if (!/^[A-Z]{3}$/.test(moneda)) throw new Error('Moneda como código ISO de 3 letras (EUR, USD, MXN…).');
    ev.custom_data = { value: valor, currency: moneda };
  }
  const entrada = segundos(b.mensajeria_entrada);
  salida.push({ json: {
    evento: ev,
    necesita_hash: necesitaHash,
    ph_normalizado: ph,
    contacto_id: String(b.contacto_id || ''),
    enviados: [...enviados, evento].join(','),
    fuera_de_ventana: Boolean(entrada && momento - entrada > VENTANA_CLIC),
    config: c,
  } });
}
return salida;

// Monta el cuerpo para POST /{dataset}/events. Por defecto solo sale con test_event_code: el envío real exige
// ENVIO_REAL_APROBADO = true en Configuración (igual que `capi.py enviar --real --confirmo`).
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const c = j.config || {};
  const ev = JSON.parse(JSON.stringify(j.evento));
  if (j.necesita_hash) {
    if (!/^[0-9a-f]{64}$/.test(String(j.ph_hash || ''))) throw new Error('Falta el hash SHA-256 del teléfono.');
    ev.user_data.ph = [j.ph_hash];
  }
  const dataset = String(c.DATASET_ID || '');
  if (!/^\d{6,20}$/.test(dataset)) throw new Error('Rellena DATASET_ID en Configuración.');
  const cuerpo = { data: [ev] };
  const codigo = String(c.TEST_EVENT_CODE || '').trim();
  if (codigo && !codigo.startsWith('<<')) {
    cuerpo.test_event_code = codigo;
  } else if (c.ENVIO_REAL_APROBADO !== true) {
    throw new Error('Sin TEST_EVENT_CODE no se envía nada: un evento real de prueba ensucia el dataset. '
      + 'Para producción, ENVIO_REAL_APROBADO = true con el sí del cliente.');
  }
  salida.push({ json: { ...j, cuerpo, dataset } });
}
return salida;
